// Package isa holds the x86 instruction, register and directive tables the
// language server answers hover and highlighting questions from, and the
// rules for resolving an AT&T mnemonic (with its optional size suffix) to an
// instruction.
//
// Instruction data comes from two embedded JSON files: data/system.json is
// written by hand and is authoritative for system, I/O, string and
// control-transfer instructions; data/xed.json is generated by tools/xedgen
// from the Intel XED datafiles. When both define the same Name, system.json
// wins. Registers and directives are Go tables (registers.go, directives.go)
// because they are small and rarely change.
package isa

import (
	"embed"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"strings"
	"sync"
)

// Level is an x86-64 micro-architecture level from the psABI: 1..4 for
// x86-64-v1..v4. 0 means unknown, or an ISA extension outside the level
// scheme (AES, SHA, VMX ...), which is reported by its ISA set name instead.
// Levels above the baseline only make sense for 64-bit code but are
// reported regardless of mode.
type Level int

// Form is one operand pattern of an instruction.
type Form struct {
	Operands string `json:"operands,omitempty"` // AT&T operand order, e.g. "imm8, r/m8"; "" for no operands
	ISASet   string `json:"isaSet,omitempty"`   // XED ISA_SET, e.g. "BMI2", "AVX512F_512", "I386"
	Level    Level  `json:"level,omitempty"`    // derived from ISASet at load time when left 0
}

// Instruction describes one mnemonic.
//
// Notes is an addition to the original contract: a short free-text caveat
// that does not fit the structured fields and that matters when reading
// system code, e.g. "IOPL-sensitive", "#UD in real and virtual-8086 mode",
// or which operand-size spelling does what. Empty for most instructions.
//
// CPL deliberately has no omitempty: 0 means privileged, so a missing field
// must not be confused with "not stated" when the JSON is read back.
type Instruction struct {
	Name           string   `json:"name"`
	Summary        string   `json:"summary"`
	Category       string   `json:"category,omitempty"`
	CPL            int      `json:"cpl"`
	Modes          string   `json:"modes,omitempty"`
	FlagsRead      string   `json:"flagsRead,omitempty"`
	FlagsWritten   string   `json:"flagsWritten,omitempty"`
	FlagsUndefined string   `json:"flagsUndefined,omitempty"`
	Forms          []Form   `json:"forms,omitempty"`
	Aliases        []string `json:"aliases,omitempty"`
	Notes          string   `json:"notes,omitempty"`
}

// Register describes one register name usable as %name.
type Register struct {
	Name    string // without '%', lowercase
	Class   string // "gpr", "segment", "control", "debug", "x87", "mmx", "xmm", "ymm", "zmm", "mask", "flags", "ip"
	Width   int    // bits
	Summary string
	Modes   string // "64" when only valid in long mode; "" = all
	Bits    string // optional one-line bit layout, e.g. for control registers
}

// Directive describes one GNU as directive.
type Directive struct {
	Name    string // with leading '.'
	Summary string
	Syntax  string
}

//go:embed data/*.json
var dataFS embed.FS

const (
	systemFile = "data/system.json"
	xedFile    = "data/xed.json"
)

// index maps every lowercase name and alias to its instruction.
type index struct {
	byName map[string]*Instruction
	all    []*Instruction
}

var (
	loadOnce     sync.Once
	defaultIndex *index
	loadErr      error
)

// load parses the embedded tables once. The data is compiled in, so a parse
// failure is a build defect rather than a runtime condition; it is kept in
// loadErr (see DataError) and the index degrades to whatever did parse, so a
// broken generated file cannot take the hand-written table down with it.
func load() *index {
	loadOnce.Do(func() {
		sys, errSys := readTable(dataFS, systemFile)
		xed, errXed := readTable(dataFS, xedFile)
		loadErr = errors.Join(errSys, errXed)
		defaultIndex = buildIndex(xed, sys)
	})
	return defaultIndex
}

// DataError reports a failure to parse the embedded instruction tables, or
// nil. The server can log it at startup; tests assert it is nil.
func DataError() error {
	load()
	return loadErr
}

// readTable decodes one embedded JSON table. A missing file is not an error:
// xed.json is generated and may not exist in a fresh checkout's history.
func readTable(fsys fs.FS, name string) ([]Instruction, error) {
	raw, err := fs.ReadFile(fsys, name)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("isa: read %s: %w", name, err)
	}
	var out []Instruction
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, fmt.Errorf("isa: parse %s: %w", name, err)
	}
	return out, nil
}

// buildIndex merges layers in increasing precedence: an instruction in a
// later layer replaces any earlier instruction with the same Name outright
// (its aliases go with it), and its names and aliases shadow any earlier key.
// Within one layer a Name beats another entry's alias, so a generated table
// that lists, say, the SSE2 movsd as a name is not hijacked by a string-move
// alias in the same file.
func buildIndex(layers ...[]Instruction) *index {
	type entry struct {
		inst  *Instruction
		layer int
	}
	byCanon := map[string]entry{}
	var order []string
	for li, layer := range layers {
		for i := range layer {
			inst := normalize(layer[i])
			if inst.Name == "" {
				continue
			}
			if _, seen := byCanon[inst.Name]; !seen {
				order = append(order, inst.Name)
			}
			byCanon[inst.Name] = entry{&inst, li}
		}
	}

	ix := &index{byName: make(map[string]*Instruction, len(byCanon)*2)}
	// rank records which layer and kind (alias=0, name=1) set a key, so the
	// precedence rules above hold regardless of iteration order.
	type rank struct{ layer, kind int }
	ranks := map[string]rank{}
	set := func(key string, inst *Instruction, r rank) {
		if key == "" {
			return
		}
		if old, ok := ranks[key]; ok && (old.layer > r.layer || (old.layer == r.layer && old.kind > r.kind)) {
			return
		}
		ranks[key] = r
		ix.byName[key] = inst
	}
	for _, name := range order {
		e := byCanon[name]
		ix.all = append(ix.all, e.inst)
		set(name, e.inst, rank{e.layer, 1})
		for _, a := range e.inst.Aliases {
			set(a, e.inst, rank{e.layer, 0})
		}
	}
	return ix
}

// normalize lowercases the lookup keys and fills each form's Level from its
// ISA set when the source left it 0, so the hand-written table does not have
// to repeat what LevelForISASet already knows.
func normalize(in Instruction) Instruction {
	in.Name = strings.ToLower(strings.TrimSpace(in.Name))
	if len(in.Aliases) > 0 {
		aliases := make([]string, 0, len(in.Aliases))
		for _, a := range in.Aliases {
			aliases = append(aliases, strings.ToLower(strings.TrimSpace(a)))
		}
		in.Aliases = aliases
	}
	if len(in.Forms) > 0 {
		forms := make([]Form, len(in.Forms))
		copy(forms, in.Forms)
		for i := range forms {
			if forms[i].Level == 0 {
				forms[i].Level = LevelForISASet(forms[i].ISASet)
			}
		}
		in.Forms = forms
	}
	return in
}

// sizeSuffixes are the AT&T operand-size suffixes Lookup may strip.
const sizeSuffixes = "bwlq"

func (ix *index) lookup(word string) (*Instruction, string, bool) {
	w := strings.ToLower(strings.TrimSpace(word))
	if inst, ok := ix.byName[w]; ok {
		return inst, "", true
	}
	// Only one suffix, and only after the exact match failed: setb, jb,
	// movsb, cwtl and friends are whole mnemonics and must never be split.
	if n := len(w); n > 1 && strings.IndexByte(sizeSuffixes, w[n-1]) >= 0 {
		if inst, ok := ix.byName[w[:n-1]]; ok {
			return inst, w[n-1:], true
		}
	}
	return nil, "", false
}

// Lookup resolves an AT&T mnemonic. Exact match (including aliases) wins;
// only then is a single trailing size suffix (b, w, l, q) stripped and the
// base looked up. setb, jb, movsb, cwtl, scasb resolve exactly and are never
// split. suffix is "" when matched exactly. Matching is case-insensitive.
func Lookup(word string) (inst *Instruction, suffix string, ok bool) {
	return load().lookup(word)
}

// prefixes are words that may stand in mnemonic position but modify the
// following instruction rather than being one. The segment registers are
// here because GAS accepts them as override prefixes written as mnemonics
// ("es; movsb", "fs lodsl").
var prefixes = map[string]bool{
	"rep": true, "repe": true, "repz": true, "repne": true, "repnz": true,
	"lock":   true,
	"data16": true, "data32": true, "addr16": true, "addr32": true,
	"rex": true, "rex64": true,
	"cs": true, "ds": true, "es": true, "fs": true, "gs": true, "ss": true,
	"notrack": true, "xacquire": true, "xrelease": true, "bnd": true,
	"{vex}": true, "{vex2}": true, "{vex3}": true, "{evex}": true,
	"{rex}": true, "{rex2}": true, "{load}": true, "{store}": true,
	"{disp8}": true, "{disp16}": true, "{disp32}": true, "{nooptimize}": true,
}

// IsPrefix reports whether word is an instruction prefix. Besides the fixed
// set it accepts GAS's explicit REX spellings rex.w, rex.wrxb and so on.
func IsPrefix(word string) bool {
	w := strings.ToLower(strings.TrimSpace(word))
	if prefixes[w] {
		return true
	}
	if bits, ok := strings.CutPrefix(w, "rex."); ok && bits != "" {
		return strings.Trim(bits, "wrxb") == ""
	}
	return false
}
